#[cfg(test)]
mod python_parity {
    use super::*;

    /// Captured from the Python module at generation time: (architecture, its numeric fields, the FNV-1a of
    /// its pattern). The port fails the build if it drifts from the original.
    static EXPECTED: &[(&str, &[(&str, u64)], u32)] = &[
    ("fpga", &[("logic_cells", 1024), ("lut_size", 6), ("total_gates", 65536)], 1506458565),
    ("cellular", &[("cells", 1048576), ("neighbors_per_cell", 8)], 4279136005),
    ("neural", &[("neurons", 4096), ("weights_per_neuron", 16), ("total_synapses", 65536)], 171764421),
    ("cam", &[("entries", 65536), ("key_width", 32), ("value_width", 32)], 2829755045),
    ("quantum", &[("qubits", 2048), ("state_vector_size", 2048)], 3496254917),
    ("ising", &[("spins", 65536)], 3657293445),
    ("hopfield", &[("neurons", 4096), ("attractor_basins", 512)], 662444613),
    ("boltzmann", &[("units", 2048)], 2398537925),
    ("gnn", &[("nodes", 8192), ("edges_supported", 131072)], 2477438917),
    ("tcam", &[("entries", 65536), ("bits_per_trit", 2)], 3569120549),
    ("systolic", &[("total_pes", 1024)], 709281944),
    ("sparse_attention", &[("context_length", 8192)], 1107832725),
    ("hdc", &[("hypervector_dim", 10000)], 1164370565),
    ("holographic", &[("slots", 1024)], 3923263554),
    ("onn", &[("oscillators", 4096)], 3885397832),
    ];

    fn ported(name: &str) -> Pattern {
        let (_, _, _default) = architectures().into_iter().find(|(n, _, _)| *n == name).unwrap();
        match name {
            "fpga" => pattern_fpga(64),
            "cellular" => pattern_cellular_automaton(1024),
            "neural" => pattern_neural_network(4096),
            "cam" => pattern_content_addressable(65536),
            "quantum" => pattern_quantum_simulator(2048),
            "ising" => pattern_ising_spin_glass(65536),
            "hopfield" => pattern_hopfield_attractor(4096),
            "boltzmann" => pattern_boltzmann_machine(2048),
            "gnn" => pattern_gnn_accelerator(8192),
            "tcam" => pattern_tcam(65536),
            "systolic" => pattern_systolic_array(32),
            "sparse_attention" => pattern_sparse_attention(8192),
            "hdc" => pattern_hyperdimensional_computing(10000),
            "holographic" => pattern_holographic_associative(1024),
            "onn" => pattern_oscillatory_neural_network(4096),
            other => panic!("no port for {}", other),
        }
    }

    #[test]
    fn every_architecture_matches_python() {
        for (name, numbers, fnv) in EXPECTED {
            let p = ported(name);
            assert_eq!(p.pattern_hash(), *fnv, "{} pattern differs from the module's", name);
            for (k, v) in numbers.iter() {
                assert_eq!(p.number(k), Some(*v), "{}.{} differs from the module's", name, k);
            }
            assert!(!p.name.is_empty(), "{} has an empty name", name);
        }
    }

    #[test]
    fn no_function_returns_a_placeholder() {
        for (name, _, _) in architectures() {
            let p = ported(name);
            assert!(!p.pattern.is_empty(), "{} produced an empty pattern", name);
            assert!(p.pattern.iter().any(|b| *b != 0), "{} produced an all-zero pattern", name);
            assert!(p.numbers.iter().all(|(_, v)| *v != 0), "{} has a zeroed field", name);
        }
    }

    #[test]
    fn constants_are_consistent_with_the_geometry() {
        assert_eq!(L3_CELLS, L3_SIZE * 8);
        assert_eq!(L3_TOTAL_TRANSISTORS, L3_CELLS * L3_TRANSISTORS_PER_CELL);
        assert_ne!(L3_SIZE, 0, "L3_SIZE is zeroed again");
        assert_eq!(ARCHITECTURES, 15);
    }
}
